                         } catch (final Exception e) {
                             // ignore
                         }

                     }
                 };
                 Runtime.getRuntime().addShutdownHook(shutdownHook);
             }

             setChanged();
             notifyObservers(SIGNAL_STARTED);

         } catch (final MultiException e) {

