             logger.info("----------------------------------------------------------");
             logger.info("ERROR: Could not bind to port because " + e.getMessage());
             logger.info(e.toString());
             logger.info("----------------------------------------------------------");
             setChanged();
             notifyObservers(SIGNAL_ERROR);

         } catch (final Exception e) {
             e.printStackTrace();
             setChanged();
             notifyObservers(SIGNAL_ERROR);
